  resumo: GITHUB_STEP_SUMMARY ? (texto) => appendFileSync(GITHUB_STEP_SUMMARY, texto) : undefined,
  avisar:
    GITHUB_ACTIONS === "true"
      ? (mensagem) => console.log(`::warning title=Cobertura das linhas novas::${mensagem}`)
      : undefined,
});

