128	 */
129	export function agruparFaixas(numeros) {
130	  /** @type {string[]} */
131	  const faixas = [];
132	  let inicio = numeros[0];
133	  for (let i = 1; i <= numeros.length; i++) {
134	    if (numeros[i] === numeros[i - 1] + 1) continue;
135	    const fim = numeros[i - 1];
136	    faixas.push(inicio === fim ? `${inicio}` : `${inicio}-${fim}`);
137	    inicio = numeros[i];
138	  }
139	  return faixas.join(", ");
140	}
