142	/**
143	 * Resumo em Markdown, para o terminal e para o resumo do job no GitHub Actions.
144	 * @param {Resultado} resultado
145	 * @param {string} base
146	 */
147	export function formatarResumo(resultado, base) {
148	  const titulo = `### Cobertura das linhas novas contra \`${base}\``;
149	  if (resultado.percentual === null) {
150	    return `${titulo}\n\nNenhuma linha nova de código medido (src/ e scripts/).\n`;
151	  }
152	  const situacao =
153	    resultado.percentual < COBERTURA_MINIMA
154	      ? `**Abaixo do mínimo de ${COBERTURA_MINIMA}%.**`
155	      : `Mínimo: ${COBERTURA_MINIMA}%.`;
156	  const linhas = resultado.arquivos.map(
157	    ({ arquivo, total, cobertas, descobertas }) =>
158	      `| \`${arquivo}\` | ${total} | ${cobertas} | ${formatarPercentual((cobertas / total) * 100)} | ${agruparFaixas(descobertas) || "—"} |`,
159	  );
160	  return [
161	    titulo,
162	    "",
163	    `**${formatarPercentual(resultado.percentual)}** das ${resultado.total} linhas novas medidas rodam nos testes unitários (${resultado.cobertas} cobertas). ${situacao}`,
164	    "",
165	    "| arquivo | linhas novas | cobertas | % | linhas sem teste |",
166	    "|---|---:|---:|---:|---|",
167	    ...linhas,
168	    "",
169	  ].join("\n");
170	}
