176	 * @property {(texto: string) => void} escrever saída padrão
177	 * @property {(texto: string) => void} erro saída de erro
178	 * @property {((texto: string) => void) | undefined} [resumo] resumo do job no GitHub Actions
179	 * @property {((mensagem: string) => void) | undefined} [avisar] aviso no GitHub Actions
180	 */
