184	 * porque a medição só enxerga os testes unitários. Devolve o código de saída.
185	 * @param {string[]} bases
186	 * @param {Dependencias} dependencias
187	 */
188	export function executar(bases, { lerLcov: lerArquivoLcov, diff, escrever, erro, resumo, avisar }) {
189	  if (bases.length === 0) {
190	    erro("Uso: node scripts/cobertura-diff.mjs <base> [<base> ...]\n");
191	    return 1;
192	  }
193	  let lcov;
194	  try {
195	    lcov = lerArquivoLcov();
196	  } catch {
197	    erro("coverage/lcov.info não encontrado. Rode `pnpm test:coverage` antes.\n");
198	    return 1;
199	  }
200	  const cobertura = lerLcov(lcov);
201	  for (const base of bases) {
202	    const resultado = cruzarCobertura(cobertura, lerLinhasNovas(diff(base, [...cobertura.keys()])));
203	    const texto = formatarResumo(resultado, base);
204	    escrever(`${texto}\n`);
205	    resumo?.(`${texto}\n`);
