207	      avisar?.(
208	        `Cobertura das linhas novas contra ${base}: ${formatarPercentual(resultado.percentual)} (mínimo: ${COBERTURA_MINIMA}%).`,
209	      );
210	    }
211	  }
212	  return 0;
