20	 * Soma o `message.usage` das respostas do assistente, contando cada `message.id` uma vez: o
21	 * Claude Code grava uma linha por bloco da resposta, todas com o mesmo id e o mesmo `usage`.
22	 * @param {string[]} conteudos conteúdo de cada `.jsonl`
23	 * @returns {Uso}
24	 */
25	export function somarUso(conteudos) {
26	  /** @type {Map<string, { model?: string, usage: Record<string, number> }>} */
27	  const respostas = new Map();
28	  let linhasInvalidas = 0;
29	  for (const conteudo of conteudos) {
30	    for (const linha of conteudo.split(/\r?\n/)) {
31	      if (!linha.trim()) continue;
32	      let registro;
33	      try {
34	        registro = JSON.parse(linha);
35	      } catch {
36	        linhasInvalidas++;
37	        continue;
38	      }
39	      const mensagem = registro?.message;
40	      if (registro?.type === "assistant" && mensagem?.id && mensagem.usage) {
41	        respostas.set(mensagem.id, mensagem);
42	      }
43	    }
44	  }
45	  /** @type {Uso} */
46	  const uso = {
47	    entrada: 0,
48	    saida: 0,
49	    cacheCriacao: 0,
50	    cacheLeitura: 0,
51	    modelos: [],
52	    mensagens: respostas.size,
53	    linhasInvalidas,
54	  };
55	  for (const { model, usage } of respostas.values()) {
56	    uso.entrada += usage.input_tokens ?? 0;
57	    uso.saida += usage.output_tokens ?? 0;
58	    uso.cacheCriacao += usage.cache_creation_input_tokens ?? 0;
59	    uso.cacheLeitura += usage.cache_read_input_tokens ?? 0;
60	    // `<synthetic>`: mensagens que o próprio Claude Code escreve, sem chamar o modelo.
61	    if (model && model !== "<synthetic>" && !uso.modelos.includes(model)) uso.modelos.push(model);
62	  }
63	  return uso;
64	}
65	
66	/**
67	 * Número com ponto de milhar, como no resto da tabela: 8654754 -> "8.654.754".
68	 * @param {number} numero
69	 */

